def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 2 or no_water >= 2:
            return float(min(budget, 35.0))
        return float(min(budget, 8.0))

    prev_bids = []
    rich_prev_bids = []
    affordable_prev_bids = []
    desperate_count = 0
    high_pressure_count = 0

    for opp in alive:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev['bid']
            prev_bids.append(bid)
            if bid >= 100:
                high_pressure_count += 1
            if opp.get('budget', 0) >= bid:
                affordable_prev_bids.append(bid)
            if opp.get('budget', 0) >= 200:
                rich_prev_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_affordable = max(affordable_prev_bids) if affordable_prev_bids else highest_prev
    highest_rich = max(rich_prev_bids) if rich_prev_bids else highest_prev

    low_supply = supply <= 17
    high_supply = supply >= 22

    critical = hp <= 2 or no_water >= 2
    pressured = hp <= 4 or no_water >= 1

    if critical:
        if low_supply:
            bid = max(95.0, highest_affordable + 2.0)
        else:
            bid = max(75.0, highest_affordable + 1.5)
        return float(min(budget, bid))

    if low_supply:
        if high_pressure_count >= 2:
            bid = 12.0
        elif pressured and desperate_count >= 1:
            bid = 58.0
        elif pressured:
            bid = 42.0
        else:
            bid = 10.0
        return float(min(budget, bid))

    if high_supply:
        if highest_affordable > 0:
            target = min(highest_affordable + 1.5, 88.0)
        else:
            target = 46.0
        if pressured:
            target = max(target, 62.0)
        return float(min(budget, target))

    target = 38.0
    if highest_rich >= 110:
        target = 24.0 if not pressured else 60.0
    elif highest_affordable > 0:
        target = max(40.0, min(highest_affordable + 1.2, 78.0))

    if day >= 8 and hp >= 6 and no_water == 0:
        target = min(target, 28.0)

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        target = DAILY_SALARY * 0.45
        return max(0.0, min(budget, target))

    # Read yesterday bids from each opponent's previous_trace (single-step reaction)
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate pressure from yesterday
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_highest = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid
        # If someone already bid extremely high, we must match to avoid losing water.
        if highest_prev_bid >= DAILY_SALARY * 1.30:
            base = highest_prev_bid + 2.0
        elif highest_prev_bid >= DAILY_SALARY * 0.90:
            base = max(second_highest + 1.0, DAILY_SALARY * 0.95)
        else:
            base = max(DAILY_SALARY * 0.60, highest_prev_bid + 3.0)
    else:
        base = DAILY_SALARY * 0.70

    # Adjust for our own urgency (hp low or accumulating no-water days)
    urgency = 0
    if hp <= 2.0:
        urgency += 3
    elif hp <= 4.0:
        urgency += 2
    if no_water_days >= 2:
        urgency += 2
    elif no_water_days >= 1:
        urgency += 1

    # Supply scaling: when supply is tight, bid more aggressively.
    # supply range is 15..25, so normalize to [0,1].
    norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    tightness = 1.0 - max(0.0, min(1.0, norm))

    # Convert urgency/tightness into a multiplier
    multiplier = 1.0 + 0.18 * urgency + 0.10 * tightness
    target = base * multiplier

    # Hard caps to avoid running out too early; still bid enough to compete.
    # If we are in danger (hp low), allow higher cap.
    if hp <= 3.0 or no_water_days >= 2:
        cap = DAILY_SALARY * 1.25
    else:
        cap = DAILY_SALARY * 1.05

    target = min(target, cap)

    # Final budget safety
    if budget <= 0.0:
        return 0.0
    return max(0.0, min(budget, float(target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if day == 1 or not yesterday_bids:
        # First day or no trace: bid based on hp and budget
        if hp <= 2:
            # desperate: bid high to survive
            return min(budget, DAILY_SALARY * 0.9)
        else:
            # comfortable: bid moderate
            base_bid = DAILY_SALARY * 0.5
            # if budget is low, scale down
            bid = max(base_bid, budget * 0.3)
            return min(budget, bid)
    else:
        # Use trace to adapt
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)
        # Eric likely bids high (130+), Alex mid (80-140)
        if hp <= 3:
            # need water, outbid highest previous by a margin
            target = highest_prev_bid + 5
            return min(budget, max(target, DAILY_SALARY * 0.3))
        else:
            # healthy: bid slightly above average to win cheaply
            target = max(avg_prev_bid + 2, DAILY_SALARY * 0.4)
            return min(budget, target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10 

    my_current_hp = my_status['hp']
    my_current_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_current_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    base_bid = DAILY_SALARY * 0.55

    if my_current_hp <= WATER_REQ:
        return min(my_current_budget, DAILY_SALARY * 0.95)

    days_left = EPISODE_DAYS - current_day
    if days_left <= 2 and my_current_hp < 2 * WATER_REQ:
        base_bid = max(base_bid, DAILY_SALARY * 0.8)

    num_agents_can_get_water = int(current_supply // WATER_REQ)

    if num_agents_can_get_water < (num_alive_opponents + 1):
        scarcity_multiplier = 1.0 + (num_alive_opponents + 1 - num_agents_can_get_water) * 0.15
        base_bid *= scarcity_multiplier
        base_bid = max(base_bid, DAILY_SALARY * 0.65)

    if highest_prev_bid > 0:
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            base_bid = max(base_bid, highest_prev_bid + 5.0)
        elif highest_prev_bid < DAILY_SALARY * 0.4:
            base_bid = min(base_bid, highest_prev_bid + 10.0)
        else:
            base_bid = max(base_bid, highest_prev_bid + 2.0)

    is_cindy_alive = any(o['agent_id'] == 'Cindy' for o in alive_opponents)
    is_alex_alive = any(o['agent_id'] == 'Alex' for o in alive_opponents)

    if is_cindy_alive:
        base_bid = max(base_bid, 125.0)

    if is_alex_alive:
        base_bid = max(base_bid, 85.0)

    final_bid = min(my_current_budget, base_bid)
    final_bid = max(1.0, final_bid)

    return final_bid
